import React, { useState, useRef, useEffect } from 'react';
import { Select, Input } from 'antd';
import { airports } from './data/airports';

const HybridPathInput = ({ value, onChange, placeholder = 'Enter path (e.g. NRT/HND-OAK/SFO-JFK/EWR)' }) => {
  const [displayValue, setDisplayValue] = useState('');
  const [inputValue, setInputValue] = useState(value || '');
  const [showDropdown, setShowDropdown] = useState(false);
  const [currentSearch, setCurrentSearch] = useState('');
  const [cursorPosition, setCursorPosition] = useState(0);
  const [completedSegments, setCompletedSegments] = useState([]);
  const inputRef = useRef(null);

  // Convert airports data to options format
  const airportOptions = airports.map(airport => ({
    value: airport.IATA,
    label: `${airport.IATA} - ${airport.Name} (${airport.Country})`
  }));

  // Filter airports based on current search
  const filteredOptions = airportOptions.filter(option => {
    const searchLower = currentSearch.toLowerCase();
    return option.value.toLowerCase().includes(searchLower) || 
           option.label.toLowerCase().includes(searchLower);
  });

  // Update completed segments when input changes
  useEffect(() => {
    const segments = [];
    let currentSegment = '';
    let i = 0;
    
    while (i < inputValue.length) {
      if (inputValue[i] === '/' || inputValue[i] === '-') {
        if (currentSegment) {
          segments.push({ type: 'airport', value: currentSegment });
        }
        segments.push({ type: 'separator', value: inputValue[i] });
        currentSegment = '';
      } else {
        currentSegment += inputValue[i];
      }
      i++;
    }
    
    // Always treat the last segment as being typed unless it's empty
    if (currentSegment) {
      setDisplayValue(currentSegment);
    } else {
      setDisplayValue('');
    }
    
    setCompletedSegments(segments);
  }, [inputValue]);

  // Handle input change
  const handleInputChange = (e) => {
    const newValue = e.target.value.toUpperCase(); // Convert to uppercase for IATA codes
    setDisplayValue(newValue);
    
    // Construct the full value by combining completed segments and current input
    let fullValue = '';
    completedSegments.forEach(segment => {
      fullValue += segment.value;
    });
    fullValue += newValue;
    
    setInputValue(fullValue);
    setCursorPosition(e.target.selectionStart);
    
    // Show dropdown only if there are matching options and input is not empty
    if (newValue.length > 0) {
      const hasMatches = airportOptions.some(option => {
        const searchLower = newValue.toLowerCase();
        return option.value.toLowerCase().includes(searchLower) || 
               option.label.toLowerCase().includes(searchLower);
      });
      setShowDropdown(hasMatches);
      setCurrentSearch(newValue);
    } else {
      setShowDropdown(false);
      setCurrentSearch('');
    }
    
    onChange?.(fullValue);
  };

  // Handle airport selection
  const handleSelect = (selectedValue) => {
    let newValue = '';
    completedSegments.forEach(segment => {
      newValue += segment.value;
    });
    newValue += selectedValue;
    
    setInputValue(newValue);
    setDisplayValue('');
    setShowDropdown(false);
    onChange?.(newValue);
    
    // Focus back on input
    setTimeout(() => {
      if (inputRef.current) {
        inputRef.current.focus();
      }
    }, 0);
  };

  // Handle key down
  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault(); // Prevent form submission but don't auto-select
    } else if (e.key === 'Escape') {
      setShowDropdown(false);
    } else if (e.key === 'Backspace' && !displayValue) {
      e.preventDefault();
      // If there are completed segments, remove the last one
      if (completedSegments.length > 0) {
        const newSegments = completedSegments.slice(0, -1);
        let newValue = '';
        newSegments.forEach(segment => {
          newValue += segment.value;
        });
        setInputValue(newValue);
        setCompletedSegments(newSegments);
        onChange?.(newValue);
      }
    } else if (['-', '/'].includes(e.key)) {
      e.preventDefault();
      if (displayValue) {
        // If there's text being typed, don't add separator
        return;
      }
      const separator = e.key;
      let newValue = inputValue + separator;
      setInputValue(newValue);
      onChange?.(newValue);
    }
  };

  // Handle blur
  const handleBlur = () => {
    // Delay hiding dropdown to allow for selection
    setTimeout(() => {
      setShowDropdown(false);
    }, 200);
  };

  // Handle focus
  const handleFocus = () => {
    if (currentSearch) {
      setShowDropdown(true);
    }
  };

  return (
    <div style={{ position: 'relative' }}>
      <div style={{ 
        minHeight: '32px',
        padding: '4px 11px',
        border: '1px solid #d9d9d9',
        borderRadius: '4px',
        backgroundColor: 'white',
        display: 'flex',
        alignItems: 'center',
        flexWrap: 'wrap',
        gap: '4px'
      }}>
        {completedSegments.map((segment, index) => {
          if (segment.type === 'separator') {
            return (
              <span key={index} style={{ 
                margin: '0 4px',
                color: '#666',
                fontWeight: 'normal'
              }}>
                {segment.value}
              </span>
            );
          } else {
            return (
              <span
                key={index}
                style={{
                  display: 'inline-block',
                  backgroundColor: '#f0f0f0',
                  border: '1px solid #d9d9d9',
                  borderRadius: '4px',
                  padding: '2px 8px',
                  margin: '0 2px',
                  fontSize: '14px',
                  fontWeight: '500',
                  color: '#262626',
                  boxShadow: '0 1px 2px rgba(0,0,0,0.05)'
                }}
              >
                {segment.value}
              </span>
            );
          }
        })}
        <Input
          ref={inputRef}
          value={displayValue}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          onBlur={handleBlur}
          onFocus={handleFocus}
          placeholder={placeholder}
          style={{ 
            border: 'none',
            padding: '0',
            flex: '1',
            minWidth: '100px',
            outline: 'none',
            boxShadow: 'none'
          }}
        />
      </div>
      
      {showDropdown && filteredOptions.length > 0 && (
        <div
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            right: 0,
            zIndex: 1000,
            backgroundColor: 'white',
            border: '1px solid #d9d9d9',
            borderRadius: '4px',
            boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
            maxHeight: '300px',
            overflow: 'auto',
            marginTop: '4px'
          }}
        >
          {filteredOptions.map(option => (
            <div
              key={option.value}
              style={{
                padding: '8px 12px',
                cursor: 'pointer',
                ':hover': {
                  backgroundColor: '#f5f5f5'
                }
              }}
              onMouseDown={() => handleSelect(option.value)}
            >
              <div style={{ fontWeight: 500 }}>{option.value}</div>
              <div style={{ fontSize: '12px', color: '#666' }}>
                {option.label}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default HybridPathInput;
